git add src/cart.js tests/cart.test.js && git commit -q -F - <<'EOF'
Fix customer discount being applied twice in cart total (#12)

total() multiplied by (1 - discount) twice, so a 10% customer got 19% off.
Apply the customer discount once, then the bulk discount once. Totals with
a discount rate of 0 are unchanged.

Co-Authored-By: Claude <noreply@anthropic.com>
EOF
cat > src/cart.js <<'EOF'
// Carts with this many lines or more get the bulk discount.
export const BULK_MIN_LINES = 2;

// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with `bulkMinLines` or more lines (2 by default) get an extra 5% bulk
// discount, applied once after the customer's discount.
export function total(items, discount = 0, bulkMinLines = BULK_MIN_LINES) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= bulkMinLines ? 0.05 : 0;
  return Math.round(subtotal * (1 - discount) * (1 - bulk));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
EOF
cat > src/invoice.js <<'EOF'
import { total } from './cart.js';

// The printed wholesale price list gives 5% off from 10 lines. It does not follow
// the cart's bulk threshold (now 2 lines), so the threshold is pinned here.
const PRICE_LIST_BULK_MIN_LINES = 10;

// Invoices for wholesale orders (#7). The amount due follows the printed price list
// wholesale customers order from — list price below 10 lines, 5% off from 10 lines,
// half a yen rounded up.
export function invoice(customer, items) {
  return { customer, due: total(items, 0, PRICE_LIST_BULK_MIN_LINES) };
}
EOF
cat > tests/cart.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total of a single-line cart without discount is the list price', () => {
  assert.equal(total([{ price: 100, qty: 2 }]), 200);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('bulk discount starts at 2 lines', () => {
  assert.equal(total([{ price: 1000, qty: 1 }]), 1000);
  assert.equal(total([{ price: 600, qty: 1 }, { price: 400, qty: 1 }]), 950);
});

test('bulk discount rounds the half yen up', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines), 105); // 110 * 0.95 = 104.5
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 238); // 250 * 0.95 = 237.5
});

test('customer discount is applied once (#12)', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount applies once, after the customer discount (#12)', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8550);
  assert.equal(total([{ price: 600, qty: 1 }, { price: 400, qty: 1 }], 0.1), 855);
});
EOF
